<script setup lang="ts">import {Head,router,useForm} from '@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import {Button} from '@/components/ui/button';defineProps<{categories:any[];staff:any[];priorities:string[]}>();const form=useForm({name:'',description:'',default_priority:'normal',default_assignee_id:null,is_public:true,is_member:true,is_advertiser:true,is_active:true,sort_order:0});</script><template><Head title="Support Categories"/><div class="space-y-6 p-6"><PageHeader title="Support Categories" description="Manage routing and defaults."/><form class="grid gap-3 rounded-lg border bg-card p-4 md:grid-cols-4" @submit.prevent="form.post('/admin/support/categories',{onSuccess:()=>form.reset()})"><input v-model="form.name" class="h-10 rounded-md border bg-background px-3" placeholder="Name" required/><select v-model="form.default_priority" class="h-10 rounded-md border bg-background px-3"><option v-for="x in priorities" :value="x">{{x}}</option></select><select v-model="form.default_assignee_id" class="h-10 rounded-md border bg-background px-3"><option :value="null">No default assignee</option><option v-for="x in staff" :value="x.id">{{x.name}}</option></select><Button>Create</Button><textarea v-model="form.description" class="min-h-20 rounded-md border bg-background p-3 md:col-span-4"/></form><div class="space-y-3"><div v-for="c in categories" :key="c.id" class="rounded-lg border bg-card p-4"><div class="flex justify-between gap-3"><div><h2 class="font-semibold">{{c.name}}</h2><p class="text-sm text-muted-foreground">{{c.description||'No description'}} · {{c.tickets_count}} tickets</p></div><Button size="sm" variant="destructive" :disabled="c.tickets_count>0" @click="router.delete(`/admin/support/categories/${c.id}`)">Delete</Button></div></div></div></div></template>